THREE.PlaneGeometry = PlaneGeometry;

class CylinderGeometry extends BufferGeometry {
  constructor(radiusTop = 1, radiusBottom = 1, height = 1, radialSegments = 12) {
    super();
    const positions = [];
    const normals = [];
    const uvs = [];
    const indices = [];

    const halfH = height / 2;
    for (let y = 0; y <= 1; y++) {
      const v = y;
      const radius = y === 0 ? radiusTop : radiusBottom;
      const py = y === 0 ? halfH : -halfH;
      for (let x = 0; x <= radialSegments; x++) {
        const u = x / radialSegments;
        const theta = u * Math.PI * 2;
        const sinTheta = Math.sin(theta);
        const cosTheta = Math.cos(theta);

        positions.push(radius * sinTheta, py, radius * cosTheta);
        normals.push(sinTheta, 0, cosTheta);
        uvs.push(u, 1 - v);
      }
    }

    for (let x = 0; x < radialSegments; x++) {
      const a = x;
      const b = x + radialSegments + 1;
      const c = x + 1;
      const d = x + radialSegments + 2;
      indices.push(a, b, c);
      indices.push(c, b, d);
    }

    // Top cap
    const centerTopIndex = positions.length / 3;
    positions.push(0, halfH, 0); normals.push(0, 1, 0); uvs.push(0.5, 0.5);
    for (let x = 0; x <= radialSegments; x++) {
      const u = x / radialSegments;
      const theta = u * Math.PI * 2;
      positions.push(radiusTop * Math.sin(theta), halfH, radiusTop * Math.cos(theta));
      normals.push(0, 1, 0);
      uvs.push(Math.sin(theta) * 0.5 + 0.5, Math.cos(theta) * 0.5 + 0.5);
    }
    for (let x = 0; x < radialSegments; x++) {
      indices.push(centerTopIndex, centerTopIndex + x + 1, centerTopIndex + x + 2);
    }

    this.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
    this.setAttribute('normal', new BufferAttribute(new Float32Array(normals), 3));
    this.setAttribute('uv', new BufferAttribute(new Float32Array(uvs), 2));
    this.setIndex(indices);
  }
}
THREE.CylinderGeometry = CylinderGeometry;

class TorusGeometry extends BufferGeometry {
  constructor(radius = 1, tube = 0.2, radialSegments = 4, tubularSegments = 12) {
    super();
    const positions = [];
    const normals = [];
    const uvs = [];
    const indices = [];

    for (let j = 0; j <= radialSegments; j++) {
      for (let i = 0; i <= tubularSegments; i++) {
        const u = i / tubularSegments * Math.PI * 2;
        const v = j / radialSegments * Math.PI * 2;

        const x = (radius + tube * Math.cos(v)) * Math.cos(u);
        const y = tube * Math.sin(v);
        const z = (radius + tube * Math.cos(v)) * Math.sin(u);

        positions.push(x, y, z);

        const cx = radius * Math.cos(u);
        const cz = radius * Math.sin(u);
        const nx = x - cx, ny = y, nz = z - cz;
        const nLen = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;
        normals.push(nx/nLen, ny/nLen, nz/nLen);
        uvs.push(i / tubularSegments, j / radialSegments);
      }
    }

    for (let j = 1; j <= radialSegments; j++) {
      for (let i = 1; i <= tubularSegments; i++) {
        const a = (tubularSegments + 1) * j + i - 1;
        const b = (tubularSegments + 1) * (j - 1) + i - 1;
        const c = (tubularSegments + 1) * (j - 1) + i;
        const d = (tubularSegments + 1) * j + i;
        indices.push(a, b, d);
        indices.push(b, c, d);
      }
    }

    this.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
    this.setAttribute('normal', new BufferAttribute(new Float32Array(normals), 3));
    this.setAttribute('uv', new BufferAttribute(new Float32Array(uvs), 2));
    this.setIndex(indices);
  }
}
THREE.TorusGeometry = TorusGeometry;

class CircleGeometry extends BufferGeometry {
  constructor(radius = 1, segments = 12) {
    super();
    const positions = [0, 0, 0];
    const normals = [0, 1, 0];
    const uvs = [0.5, 0.5];
    const indices = [];

    for (let s = 0; s <= segments; s++) {
      const theta = (s / segments) * Math.PI * 2;
      const x = radius * Math.cos(theta);
      const z = radius * Math.sin(theta);
      positions.push(x, 0, z);
      normals.push(0, 1, 0);
      uvs.push(Math.cos(theta) * 0.5 + 0.5, Math.sin(theta) * 0.5 + 0.5);
    }
    for (let s = 1; s <= segments; s++) {
      indices.push(0, s, s + 1);
    }
    this.setAttribute('position', new BufferAttribute(new Float32Array(positions), 3));
    this.setAttribute('normal', new BufferAttribute(new Float32Array(normals), 3));
    this.setAttribute('uv', new BufferAttribute(new Float32Array(uvs), 2));
    this.setIndex(indices);
  }
}
THREE.CircleGeometry = CircleGeometry;

