class TextureLoader {
  load(url, onLoad, onProgress, onError) {
    const texture = new Texture();
    if (typeof Image === 'undefined') return texture;
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      texture.image = img;
      texture.needsUpdate = true;
      if (onLoad) onLoad(texture);
    };
    img.onerror = (e) => {
      if (onError) onError(e);
    };
    img.src = url;
    return texture;
  }
}
