// --- Meshes, InstancedMesh & Points ---
class Mesh extends Object3D {
  constructor(geometry, material) {
    super();
    this.isMesh = true;
    this.type = 'Mesh';
    this.geometry = geometry || new BufferGeometry();
    this.material = material || new MeshStandardMaterial();
  }
}
THREE.Mesh = Mesh;

class InstancedMesh extends Mesh {
  constructor(geometry, material, count = 1) {
    super(geometry, material);
    this.isInstancedMesh = true;
    this.type = 'InstancedMesh';
    this.count = count;
    this.instanceMatrix = new BufferAttribute(new Float32Array(count * 16), 16);
    this.instanceColor = new BufferAttribute(new Float32Array(count * 3), 3);
    
    // Initialize with identity matrices & white color
    const ident = new Matrix4();
    for (let i = 0; i < count; i++) {
      this.setMatrixAt(i, ident);
      this.setColorAt(i, new Color(1, 1, 1));
    }
  }

  setMatrixAt(index, matrix) {
    const arr = this.instanceMatrix.array;
    const offset = index * 16;
    const e = matrix.elements;
    for (let i = 0; i < 16; i++) arr[offset + i] = e[i];
    this.instanceMatrix.version++;
  }

  getMatrixAt(index, matrix) {
    const arr = this.instanceMatrix.array;
    const offset = index * 16;
    const e = matrix.elements;
    for (let i = 0; i < 16; i++) e[i] = arr[offset + i];
    return matrix;
  }

  setColorAt(index, color) {
    const arr = this.instanceColor.array;
    const offset = index * 3;
    arr[offset] = color.r;
    arr[offset + 1] = color.g;
    arr[offset + 2] = color.b;
    this.instanceColor.version++;
  }
}
THREE.InstancedMesh = InstancedMesh;

class Points extends Object3D {
  constructor(geometry, material) {
    super();
    this.isPoints = true;
    this.type = 'Points';
    this.geometry = geometry || new BufferGeometry();
    this.material = material || new PointsMaterial();
  }
}
THREE.Points = Points;

// --- WebGL Shaders & Real High-Performance Renderer ---
const VERTEX_SHADER_PBR = `
  attribute vec3 aPosition;
  attribute vec3 aNormal;
  attribute vec2 aUV;

  attribute vec4 aInstanceMatrix0;
  attribute vec4 aInstanceMatrix1;
  attribute vec4 aInstanceMatrix2;
  attribute vec4 aInstanceMatrix3;
  attribute vec3 aInstanceColor;

  uniform mat4 uModelMatrix;
  uniform mat4 uViewMatrix;
  uniform mat4 uProjectionMatrix;
  uniform mat4 uNormalMatrix;
  uniform int uIsInstanced;
  uniform int uHasInstanceColor;

  varying vec3 vWorldPosition;
  varying vec3 vNormal;
  varying vec2 vUV;
  varying vec3 vInstanceColor;

  void main() {
    vUV = aUV;
    vInstanceColor = (uHasInstanceColor == 1) ? aInstanceColor : vec3(1.0);

    mat4 model = uModelMatrix;
    if (uIsInstanced == 1) {
      mat4 instanceMat = mat4(aInstanceMatrix0, aInstanceMatrix1, aInstanceMatrix2, aInstanceMatrix3);
      model = uModelMatrix * instanceMat;
    }

    vec4 worldPos = model * vec4(aPosition, 1.0);
    vWorldPosition = worldPos.xyz;
    vNormal = normalize((model * vec4(aNormal, 0.0)).xyz);
    gl_Position = uProjectionMatrix * uViewMatrix * worldPos;
  }
`;

const FRAGMENT_SHADER_PBR = `
  precision mediump float;

  varying vec3 vWorldPosition;
  varying vec3 vNormal;
  varying vec2 vUV;
  varying vec3 vInstanceColor;

  uniform vec3 uColor;
  uniform vec3 uEmissive;
  uniform float uEmissiveIntensity;
  uniform float uRoughness;
  uniform float uMetalness;
  uniform float uOpacity;
  uniform int uHasMap;
  uniform sampler2D uMap;

  uniform vec3 uAmbientLight;
  uniform vec3 uDirLightPos;
  uniform vec3 uDirLightColor;
  uniform vec3 uSpotLightPos;
  uniform vec3 uSpotLightColor;
  uniform vec3 uCameraPos;

  void main() {
    vec4 baseColor = vec4(uColor * vInstanceColor, uOpacity);
    if (uHasMap == 1) {
      vec4 texColor = texture2D(uMap, vUV);
      baseColor *= texColor;
    }

    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCameraPos - vWorldPosition);

    // Directional Light Blinn-Phong Diffuse & Specular (Fast ALU)
    vec3 L_dir = normalize(uDirLightPos - vWorldPosition);
    float NdotL_dir = max(dot(N, L_dir), 0.0);
    vec3 H_dir = normalize(L_dir + V);
    float NdotH_dir = max(dot(N, H_dir), 0.0);
    float spec2 = NdotH_dir * NdotH_dir;
    float spec4 = spec2 * spec2;
    float spec16 = spec4 * spec4;
    float spec_dir = spec16 * (1.0 - uRoughness);

    // Spot Light (Fast Distance Attenuation)
    vec3 L_spot = normalize(uSpotLightPos - vWorldPosition);
    float NdotL_spot = max(dot(N, L_spot), 0.0);
    vec3 spotDelta = uSpotLightPos - vWorldPosition;
    float dist2_spot = dot(spotDelta, spotDelta);
    float atten_spot = 1.0 / (1.0 + 0.005 * dist2_spot);

    vec3 diffuse = (uAmbientLight + uDirLightColor * NdotL_dir + uSpotLightColor * NdotL_spot * atten_spot);
    vec3 specular = (uDirLightColor * spec_dir * (0.2 + 0.8 * uMetalness));
    vec3 emissive = (uEmissive * vInstanceColor) * uEmissiveIntensity;

    vec3 finalRGB = (baseColor.rgb * diffuse) + specular + emissive;
    gl_FragColor = vec4(finalRGB, baseColor.a);
  }
`;

const VERTEX_SHADER_POINTS = `
  attribute vec3 aPosition;
  uniform mat4 uModelMatrix;
  uniform mat4 uViewMatrix;
  uniform mat4 uProjectionMatrix;
  uniform float uSize;

  void main() {
    vec4 worldPos = uModelMatrix * vec4(aPosition, 1.0);
    vec4 viewPos = uViewMatrix * worldPos;
    gl_Position = uProjectionMatrix * viewPos;
    gl_PointSize = uSize * (240.0 / -viewPos.z);
  }
`;

const FRAGMENT_SHADER_POINTS = `
  precision mediump float;
  uniform vec3 uColor;
  uniform float uOpacity;

  void main() {
    vec2 coord = gl_PointCoord - vec2(0.5);
    float dist = length(coord);
    if (dist > 0.5) discard;
    float alpha = (1.0 - dist * 2.0) * uOpacity;
    gl_FragColor = vec4(uColor, alpha);
  }
`;

class WebGLRenderer {
  constructor(parameters = {}) {
    this.domElement = parameters.canvas || (typeof document !== 'undefined' ? document.createElement('canvas') : null);
    this.antialias = parameters.antialias !== false;
    this.alpha = parameters.alpha !== false;
    this.pixelRatio = 1;
    this.clearColor = new Color(0x05070d);
    this.clearAlpha = 1;
    this.shadowMap = { enabled: true, type: 'PCF' };
    
    this.info = {
      render: { calls: 0, triangles: 0, points: 0, frame: 0 },
      memory: { geometries: 0, textures: 0 }
    };

    this._ambientColor = new Color(0.1, 0.12, 0.18);
    this._dirLightPos = new Vector3(20, 40, 20);
    this._dirLightColor = new Color(0.9, 0.95, 1.0);
    this._spotLightPos = new Vector3(0, 30, 0);
    this._spotLightColor = new Color(0.4, 0.7, 1.0);
    this._blackColor = new Color(0, 0, 0);

    this.gl = null;
    this.extInstancing = null;

    if (this.domElement && typeof this.domElement.getContext === 'function') {
      const glOpts = {
        alpha: this.alpha,
        antialias: this.antialias,
        powerPreference: parameters.powerPreference || 'high-performance'
      };
      this.gl = this.domElement.getContext('webgl2', glOpts) || this.domElement.getContext('webgl', glOpts) || this.domElement.getContext('experimental-webgl', glOpts);
      if (this.gl && !this.gl.drawElementsInstanced) {
        this.extInstancing = this.gl.getExtension('ANGLE_instanced_arrays');
      }
    }

    this._programs = {};
    this._buffers = new WeakMap();
    this._instanceBuffers = new WeakMap();
    this._textures = new WeakMap();

    if (this.gl) {
      this._initGL();
    }
  }

  _initGL() {
    const gl = this.gl;
    gl.enable(gl.DEPTH_TEST);
    gl.depthFunc(gl.LEQUAL);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);

    // Compile Shaders & Cache Locations for zero per-frame stall
    const pbrProg = this._createProgram(VERTEX_SHADER_PBR, FRAGMENT_SHADER_PBR);
    this._programs.pbr = {
      program: pbrProg,
      attrs: {
        aPosition: gl.getAttribLocation(pbrProg, 'aPosition'),
        aNormal: gl.getAttribLocation(pbrProg, 'aNormal'),
        aUV: gl.getAttribLocation(pbrProg, 'aUV'),
        aInstanceMatrix0: gl.getAttribLocation(pbrProg, 'aInstanceMatrix0'),
        aInstanceMatrix1: gl.getAttribLocation(pbrProg, 'aInstanceMatrix1'),
        aInstanceMatrix2: gl.getAttribLocation(pbrProg, 'aInstanceMatrix2'),
        aInstanceMatrix3: gl.getAttribLocation(pbrProg, 'aInstanceMatrix3'),
        aInstanceColor: gl.getAttribLocation(pbrProg, 'aInstanceColor')
      },
      uniforms: {
        uModelMatrix: gl.getUniformLocation(pbrProg, 'uModelMatrix'),
        uViewMatrix: gl.getUniformLocation(pbrProg, 'uViewMatrix'),
        uProjectionMatrix: gl.getUniformLocation(pbrProg, 'uProjectionMatrix'),
        uNormalMatrix: gl.getUniformLocation(pbrProg, 'uNormalMatrix'),
        uIsInstanced: gl.getUniformLocation(pbrProg, 'uIsInstanced'),
        uHasInstanceColor: gl.getUniformLocation(pbrProg, 'uHasInstanceColor'),
        uColor: gl.getUniformLocation(pbrProg, 'uColor'),
        uEmissive: gl.getUniformLocation(pbrProg, 'uEmissive'),
        uEmissiveIntensity: gl.getUniformLocation(pbrProg, 'uEmissiveIntensity'),
        uRoughness: gl.getUniformLocation(pbrProg, 'uRoughness'),
        uMetalness: gl.getUniformLocation(pbrProg, 'uMetalness'),
        uOpacity: gl.getUniformLocation(pbrProg, 'uOpacity'),
        uHasMap: gl.getUniformLocation(pbrProg, 'uHasMap'),
        uMap: gl.getUniformLocation(pbrProg, 'uMap'),
        uAmbientLight: gl.getUniformLocation(pbrProg, 'uAmbientLight'),
        uDirLightPos: gl.getUniformLocation(pbrProg, 'uDirLightPos'),
        uDirLightColor: gl.getUniformLocation(pbrProg, 'uDirLightColor'),
        uSpotLightPos: gl.getUniformLocation(pbrProg, 'uSpotLightPos'),
        uSpotLightColor: gl.getUniformLocation(pbrProg, 'uSpotLightColor'),
        uCameraPos: gl.getUniformLocation(pbrProg, 'uCameraPos')
      }
    };

    const pointsProg = this._createProgram(VERTEX_SHADER_POINTS, FRAGMENT_SHADER_POINTS);
    this._programs.points = {
      program: pointsProg,
      attrs: {
        aPosition: gl.getAttribLocation(pointsProg, 'aPosition')
      },
      uniforms: {
        uModelMatrix: gl.getUniformLocation(pointsProg, 'uModelMatrix'),
        uViewMatrix: gl.getUniformLocation(pointsProg, 'uViewMatrix'),
        uProjectionMatrix: gl.getUniformLocation(pointsProg, 'uProjectionMatrix'),
        uSize: gl.getUniformLocation(pointsProg, 'uSize'),
        uColor: gl.getUniformLocation(pointsProg, 'uColor'),
        uOpacity: gl.getUniformLocation(pointsProg, 'uOpacity')
      }
    };
  }

  _createProgram(vSrc, fSrc) {
    const gl = this.gl;
    const vShader = gl.createShader(gl.VERTEX_SHADER);
    gl.shaderSource(vShader, vSrc);
    gl.compileShader(vShader);
    if (!gl.getShaderParameter(vShader, gl.COMPILE_STATUS)) {
      console.error('Vertex Shader Error:', gl.getShaderInfoLog(vShader));
    }

    const fShader = gl.createShader(gl.FRAGMENT_SHADER);
    gl.shaderSource(fShader, fSrc);
    gl.compileShader(fShader);
    if (!gl.getShaderParameter(fShader, gl.COMPILE_STATUS)) {
      console.error('Fragment Shader Error:', gl.getShaderInfoLog(fShader));
    }

    const program = gl.createProgram();
    gl.attachShader(program, vShader);
    gl.attachShader(program, fShader);
    gl.linkProgram(program);
    return program;
  }

  setPixelRatio(ratio) {
    this.pixelRatio = Math.max(1, Math.min(ratio, 2.0));
  }

  setSize(width, height, updateStyle = true) {
    if (!this.domElement) return;
    this.domElement.width = width * this.pixelRatio;
    this.domElement.height = height * this.pixelRatio;
    if (updateStyle) {
      this.domElement.style.width = width + 'px';
      this.domElement.style.height = height + 'px';
    }
    if (this.gl) {
      this.gl.viewport(0, 0, this.domElement.width, this.domElement.height);
    }
  }

  setClearColor(color, alpha = 1) {
    this.clearColor.set(color);
    this.clearAlpha = alpha;
  }

  _getBuffer(geometry) {
    if (this._buffers.has(geometry)) return this._buffers.get(geometry);
    const gl = this.gl;
    const posAttr = geometry.getAttribute('position');
    const normAttr = geometry.getAttribute('normal');
    const uvAttr = geometry.getAttribute('uv');
    const indexAttr = geometry.index;

    const posBuf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, posBuf);
    gl.bufferData(gl.ARRAY_BUFFER, posAttr.array, gl.STATIC_DRAW);

    let normBuf = null;
    if (normAttr) {
      normBuf = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, normBuf);
      gl.bufferData(gl.ARRAY_BUFFER, normAttr.array, gl.STATIC_DRAW);
    }

    let uvBuf = null;
    if (uvAttr) {
      uvBuf = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, uvBuf);
      gl.bufferData(gl.ARRAY_BUFFER, uvAttr.array, gl.STATIC_DRAW);
    }

    let indexBuf = null;
    if (indexAttr) {
      indexBuf = gl.createBuffer();
      gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuf);
      gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, indexAttr.array, gl.STATIC_DRAW);
    }

    const bufs = { posBuf, normBuf, uvBuf, indexBuf, vertexCount: posAttr.count, indexCount: indexAttr ? indexAttr.count : 0 };
    this._buffers.set(geometry, bufs);
    this.info.memory.geometries++;
    return bufs;
  }

  _getInstanceBuffers(node) {
    const gl = this.gl;
    let ib = this._instanceBuffers.get(node);
    if (!ib) {
      ib = {
        matrixBuf: gl.createBuffer(),
        colorBuf: gl.createBuffer(),
        matrixVersion: -1,
        colorVersion: -1
      };
      this._instanceBuffers.set(node, ib);
    }

    if (node.instanceMatrix && ib.matrixVersion !== node.instanceMatrix.version) {
      gl.bindBuffer(gl.ARRAY_BUFFER, ib.matrixBuf);
      gl.bufferData(gl.ARRAY_BUFFER, node.instanceMatrix.array, gl.DYNAMIC_DRAW);
      ib.matrixVersion = node.instanceMatrix.version;
    }

    if (node.instanceColor && ib.colorVersion !== node.instanceColor.version) {
      gl.bindBuffer(gl.ARRAY_BUFFER, ib.colorBuf);
      gl.bufferData(gl.ARRAY_BUFFER, node.instanceColor.array, gl.DYNAMIC_DRAW);
      ib.colorVersion = node.instanceColor.version;
    }

    return ib;
  }

  _getTexture(tex) {
    if (!tex || !tex.image) return null;
    if (this._textures.has(tex) && !tex.needsUpdate) return this._textures.get(tex);
    const gl = this.gl;
    const glTexture = this._textures.get(tex) || gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, glTexture);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, tex.image);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    tex.needsUpdate = false;
    this._textures.set(tex, glTexture);
    this.info.memory.textures++;
    return glTexture;
  }

  render(scene, camera) {
    if (!this.gl) return;
    const gl = this.gl;
    this.info.render.frame++;
    this.info.render.calls = 0;
    this.info.render.triangles = 0;
    this.info.render.points = 0;

    scene.updateMatrixWorld();
    camera.updateMatrixWorld();

    gl.clearColor(this.clearColor.r, this.clearColor.g, this.clearColor.b, this.clearAlpha);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

    // Reset light scratch objects to defaults (Zero per-frame allocations)
    const ambientColor = this._ambientColor.set(0.1, 0.12, 0.18);
    const dirLightPos = this._dirLightPos.set(20, 40, 20);
    const dirLightColor = this._dirLightColor.set(0.9, 0.95, 1.0);
    const spotLightPos = this._spotLightPos.set(0, 30, 0);
    const spotLightColor = this._spotLightColor.set(0.4, 0.7, 1.0);
    const black = this._blackColor.set(0, 0, 0);

    const traverseLights = (node) => {
      if (!node.visible) return;
      if (node.isLight) {
        if (node.type === 'AmbientLight') {
          ambientColor.copy(node.color).lerp(black, 1 - node.intensity);
        } else if (node.type === 'DirectionalLight') {
          dirLightPos.copy(node.position);
          dirLightColor.copy(node.color).lerp(black, 1 - node.intensity);
        } else if (node.type === 'SpotLight') {
          spotLightPos.copy(node.position);
          spotLightColor.copy(node.color).lerp(black, 1 - node.intensity);
        }
      }
      for (let i = 0; i < node.children.length; i++) traverseLights(node.children[i]);
    };
    traverseLights(scene);

    // Set divisor helper
    const setDivisor = (loc, div) => {
      if (loc < 0) return;
      if (gl.vertexAttribDivisor) {
        gl.vertexAttribDivisor(loc, div);
      } else if (this.extInstancing) {
        this.extInstancing.vertexAttribDivisorANGLE(loc, div);
      }
    };

    // Draw elements instanced helper
    const drawElementsInstanced = (mode, count, type, offset, instanceCount) => {
      if (gl.drawElementsInstanced) {
        gl.drawElementsInstanced(mode, count, type, offset, instanceCount);
      } else if (this.extInstancing) {
        this.extInstancing.drawElementsInstancedANGLE(mode, count, type, offset, instanceCount);
      }
    };

    const pbrPkg = this._programs.pbr;
    const pbrProg = pbrPkg.program;
    const pbrAttrs = pbrPkg.attrs;
    const pbrUnis = pbrPkg.uniforms;

    const pointsPkg = this._programs.points;
    const pointsProg = pointsPkg.program;
    const pointsAttrs = pointsPkg.attrs;
    const pointsUnis = pointsPkg.uniforms;

    // Upload global camera and lighting uniforms ONCE before node traversal
    gl.useProgram(pbrProg);
    gl.uniformMatrix4fv(pbrUnis.uViewMatrix, false, camera.matrixWorldInverse.elements);
    gl.uniformMatrix4fv(pbrUnis.uProjectionMatrix, false, camera.projectionMatrix.elements);
    gl.uniform3f(pbrUnis.uAmbientLight, ambientColor.r, ambientColor.g, ambientColor.b);
    gl.uniform3f(pbrUnis.uDirLightPos, dirLightPos.x, dirLightPos.y, dirLightPos.z);
    gl.uniform3f(pbrUnis.uDirLightColor, dirLightColor.r, dirLightColor.g, dirLightColor.b);
    gl.uniform3f(pbrUnis.uSpotLightPos, spotLightPos.x, spotLightPos.y, spotLightPos.z);
    gl.uniform3f(pbrUnis.uSpotLightColor, spotLightColor.r, spotLightColor.g, spotLightColor.b);
    gl.uniform3f(pbrUnis.uCameraPos, camera.position.x, camera.position.y, camera.position.z);

    let activeProg = pbrProg;

    // Traverse & Render Meshes
    const renderNode = (node) => {
      if (!node.visible) return;

      if ((node.isMesh || node.isInstancedMesh) && node.geometry) {
        if (activeProg !== pbrProg) {
          gl.useProgram(pbrProg);
          activeProg = pbrProg;
        }

        const mat = node.material;
        const bufs = this._getBuffer(node.geometry);

        // Upload Mesh-Specific Uniforms
        gl.uniformMatrix4fv(pbrUnis.uModelMatrix, false, node.matrixWorld.elements);
        gl.uniformMatrix4fv(pbrUnis.uNormalMatrix, false, node.matrixWorld.elements);

        gl.uniform3f(pbrUnis.uColor, mat.color.r, mat.color.g, mat.color.b);
        gl.uniform3f(pbrUnis.uEmissive, mat.emissive ? mat.emissive.r : 0, mat.emissive ? mat.emissive.g : 0, mat.emissive ? mat.emissive.g : 0);
        gl.uniform1f(pbrUnis.uEmissiveIntensity, mat.emissiveIntensity || 0);
        gl.uniform1f(pbrUnis.uRoughness, mat.roughness !== undefined ? mat.roughness : 0.5);
        gl.uniform1f(pbrUnis.uMetalness, mat.metalness !== undefined ? mat.metalness : 0.5);
        gl.uniform1f(pbrUnis.uOpacity, mat.opacity !== undefined ? mat.opacity : 1.0);

        if (mat.map && mat.map.image) {
          const glTex = this._getTexture(mat.map);
          gl.activeTexture(gl.TEXTURE0);
          gl.bindTexture(gl.TEXTURE_2D, glTex);
          gl.uniform1i(pbrUnis.uMap, 0);
          gl.uniform1i(pbrUnis.uHasMap, 1);
        } else {
          gl.uniform1i(pbrUnis.uHasMap, 0);
        }

        // Bind Geometry Buffers
        gl.bindBuffer(gl.ARRAY_BUFFER, bufs.posBuf);
        gl.enableVertexAttribArray(pbrAttrs.aPosition);
        gl.vertexAttribPointer(pbrAttrs.aPosition, 3, gl.FLOAT, false, 0, 0);

        if (bufs.normBuf && pbrAttrs.aNormal >= 0) {
          gl.bindBuffer(gl.ARRAY_BUFFER, bufs.normBuf);
          gl.enableVertexAttribArray(pbrAttrs.aNormal);
          gl.vertexAttribPointer(pbrAttrs.aNormal, 3, gl.FLOAT, false, 0, 0);
        }

        if (bufs.uvBuf && pbrAttrs.aUV >= 0) {
          gl.bindBuffer(gl.ARRAY_BUFFER, bufs.uvBuf);
          gl.enableVertexAttribArray(pbrAttrs.aUV);
          gl.vertexAttribPointer(pbrAttrs.aUV, 2, gl.FLOAT, false, 0, 0);
        }

        if (node.isInstancedMesh && node.count > 0) {
          gl.uniform1i(pbrUnis.uIsInstanced, 1);
          gl.uniform1i(pbrUnis.uHasInstanceColor, node.instanceColor ? 1 : 0);

          const ib = this._getInstanceBuffers(node);
          gl.bindBuffer(gl.ARRAY_BUFFER, ib.matrixBuf);

          const stride = 16 * 4;
          gl.enableVertexAttribArray(pbrAttrs.aInstanceMatrix0);
          gl.vertexAttribPointer(pbrAttrs.aInstanceMatrix0, 4, gl.FLOAT, false, stride, 0);
          setDivisor(pbrAttrs.aInstanceMatrix0, 1);

          gl.enableVertexAttribArray(pbrAttrs.aInstanceMatrix1);
          gl.vertexAttribPointer(pbrAttrs.aInstanceMatrix1, 4, gl.FLOAT, false, stride, 16);
          setDivisor(pbrAttrs.aInstanceMatrix1, 1);

          gl.enableVertexAttribArray(pbrAttrs.aInstanceMatrix2);
          gl.vertexAttribPointer(pbrAttrs.aInstanceMatrix2, 4, gl.FLOAT, false, stride, 32);
          setDivisor(pbrAttrs.aInstanceMatrix2, 1);

          gl.enableVertexAttribArray(pbrAttrs.aInstanceMatrix3);
          gl.vertexAttribPointer(pbrAttrs.aInstanceMatrix3, 4, gl.FLOAT, false, stride, 48);
          setDivisor(pbrAttrs.aInstanceMatrix3, 1);

          if (node.instanceColor && pbrAttrs.aInstanceColor >= 0) {
            gl.bindBuffer(gl.ARRAY_BUFFER, ib.colorBuf);
            gl.enableVertexAttribArray(pbrAttrs.aInstanceColor);
            gl.vertexAttribPointer(pbrAttrs.aInstanceColor, 3, gl.FLOAT, false, 3 * 4, 0);
            setDivisor(pbrAttrs.aInstanceColor, 1);
          }

          if (bufs.indexBuf) {
            gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, bufs.indexBuf);
            drawElementsInstanced(gl.TRIANGLES, bufs.indexCount, gl.UNSIGNED_SHORT, 0, node.count);
            this.info.render.triangles += (bufs.indexCount / 3) * node.count;
          }

          // Clean up divisors
          setDivisor(pbrAttrs.aInstanceMatrix0, 0);
          setDivisor(pbrAttrs.aInstanceMatrix1, 0);
          setDivisor(pbrAttrs.aInstanceMatrix2, 0);
          setDivisor(pbrAttrs.aInstanceMatrix3, 0);
          if (pbrAttrs.aInstanceColor >= 0) setDivisor(pbrAttrs.aInstanceColor, 0);

          this.info.render.calls++;
        } else {
          gl.uniform1i(pbrUnis.uIsInstanced, 0);
          gl.uniform1i(pbrUnis.uHasInstanceColor, 0);

          if (bufs.indexBuf) {
            gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, bufs.indexBuf);
            gl.drawElements(gl.TRIANGLES, bufs.indexCount, gl.UNSIGNED_SHORT, 0);
            this.info.render.triangles += bufs.indexCount / 3;
          } else {
            gl.drawArrays(gl.TRIANGLES, 0, bufs.vertexCount);
            this.info.render.triangles += bufs.vertexCount / 3;
          }
          this.info.render.calls++;
        }
      } else if (node.isPoints && node.geometry) {
        if (activeProg !== pointsProg) {
          gl.useProgram(pointsProg);
          activeProg = pointsProg;
        }

        const bufs = this._getBuffer(node.geometry);
        gl.bindBuffer(gl.ARRAY_BUFFER, bufs.posBuf);
        gl.enableVertexAttribArray(pointsAttrs.aPosition);
        gl.vertexAttribPointer(pointsAttrs.aPosition, 3, gl.FLOAT, false, 0, 0);

        gl.uniformMatrix4fv(pointsUnis.uModelMatrix, false, node.matrixWorld.elements);
        gl.uniformMatrix4fv(pointsUnis.uViewMatrix, false, camera.matrixWorldInverse.elements);
        gl.uniformMatrix4fv(pointsUnis.uProjectionMatrix, false, camera.projectionMatrix.elements);
        gl.uniform1f(pointsUnis.uSize, node.material.size || 2.0);
        gl.uniform3f(pointsUnis.uColor, node.material.color.r, node.material.color.g, node.material.color.b);
        gl.uniform1f(pointsUnis.uOpacity, node.material.opacity || 1.0);

        gl.drawArrays(gl.POINTS, 0, bufs.vertexCount);
        this.info.render.points += bufs.vertexCount;
        this.info.render.calls++;
      }

      for (let i = 0; i < node.children.length; i++) {
        renderNode(node.children[i]);
      }
    };

    renderNode(scene);
  }

  dispose() {
    // Clean up buffers & textures
  }
}
THREE.WebGLRenderer = WebGLRenderer;

if (typeof module !== "undefined" && module.exports) module.exports = THREE;
